const rawBody = $input.first().json.body || $input.first().json;

function normalize(body) {
  const contactId = body.contactId ?? body.contact_id ?? body.id ?? '';
  const name = body.contactName ?? body.full_name ?? body.name ?? '';
  const channelRaw = (body.channel ?? body.source ?? body.customData?.channel ?? '').toString().toLowerCase();
  let channel = 'unknown';
  if (channelRaw.includes('whatsapp')) channel = 'whatsapp';
  else if (channelRaw.includes('instagram') || channelRaw === 'ig') channel = 'instagram';
  else if (channelRaw.includes('messenger') || channelRaw.includes('facebook') || channelRaw.includes('fb')) channel = 'messenger';
  const message = body.message ?? body.lastMessage ?? body.message_body ?? body.body ?? '';
  const locationId = body.locationId ?? body.location_id ?? '';
  const attachmentUrl = body.attachmentUrl ?? body.attachment_url ?? body.mediaUrl ?? '';
  return { contactId, name, channel, message, locationId, attachmentUrl };
}

const current_body = normalize(rawBody);
const current_key = current_body.contactId;
const timestamp = new Date().toISOString();
const start_time = Date.now();

const result_body = { current_body, timestamp };

return [{
  key: current_key,
  body: JSON.stringify(result_body),
  timestamp,
  start_time
}];
